def flatten(lst):
    result = []
    for item in lst:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result
```

```python
def word_count(text):
    word_count = {}
    for char in text:
        if char.isalpha():
            char = char.lower()
            if char in word_count:
                word_count[char] += 1
            else:
                word_count[char] = 1
    return word_count
```

def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for i in range(2, n + 1):
            a, b = b, a + b
        return b

